/// Query parameters for [`CoreClient::get_statistics`].
#[derive(Debug, Clone, Default, PartialEq, Serialize)]
pub struct GetStatisticsQuery {
    /// (Optional) The start date of the statistics. If no value is passed, the last 30 days will be returned.
    #[serde(rename = "dateFrom", skip_serializing_if = "Option::is_none")]
    pub date_from: Option<String>,
    /// (Optional) The end date of the statistics. If no value is passed, the last 30 days will be returned.
    #[serde(rename = "dateTo", skip_serializing_if = "Option::is_none")]
    pub date_to: Option<String>,
    /// (Optional) If set, the statistics will be only returned for the given Pull Zone
    #[serde(rename = "pullZone", skip_serializing_if = "Option::is_none")]
    pub pull_zone: Option<i64>,
    /// (Optional) If set, the statistics will be only returned for the given region ID
    #[serde(rename = "serverZoneId", skip_serializing_if = "Option::is_none")]
    pub server_zone_id: Option<i64>,
    /// (Optional) If set, the respose will contain the non-2xx response
    #[serde(rename = "loadErrors", skip_serializing_if = "Option::is_none")]
    pub load_errors: Option<bool>,
    /// (Optional) If true, the statistics data will be returned in hourly groupping.
    #[serde(rename = "hourly", skip_serializing_if = "Option::is_none")]
    pub hourly: Option<bool>,
    /// (Optional) If true and hourly=true, the exact hour components of dateFrom and dateTo will be preserved instead of rounding to full-day boundaries.
    #[serde(rename = "exactRange", skip_serializing_if = "Option::is_none")]
    pub exact_range: Option<bool>,
    /// Load Origin Response Times
    #[serde(
        rename = "loadOriginResponseTimes",
        skip_serializing_if = "Option::is_none"
    )]
    pub load_origin_response_times: Option<bool>,
    /// Load Origin Traffic
    #[serde(rename = "loadOriginTraffic", skip_serializing_if = "Option::is_none")]
    pub load_origin_traffic: Option<bool>,
    /// Load Requests Served
    #[serde(rename = "loadRequestsServed", skip_serializing_if = "Option::is_none")]
    pub load_requests_served: Option<bool>,
    /// Load Bandwidth Used
    #[serde(rename = "loadBandwidthUsed", skip_serializing_if = "Option::is_none")]
    pub load_bandwidth_used: Option<bool>,
    /// Load Origin Shield Bandwidth
    #[serde(
        rename = "loadOriginShieldBandwidth",
        skip_serializing_if = "Option::is_none"
    )]
    pub load_origin_shield_bandwidth: Option<bool>,
    /// Load Geographic Traffic Distribution
    #[serde(
        rename = "loadGeographicTrafficDistribution",
        skip_serializing_if = "Option::is_none"
    )]
    pub load_geographic_traffic_distribution: Option<bool>,
    /// Load User Balance History
    #[serde(
        rename = "loadUserBalanceHistory",
        skip_serializing_if = "Option::is_none"
    )]
    pub load_user_balance_history: Option<bool>,
}

